#include "partial-tree-proof.h"
#include <algorithm>
#include <stdexcept>
namespace partial_tree {std::uint64_t hash_leaf(const std::string& s){std::uint64_t h=1469598103934665603ULL;for(unsigned char c:s){h^=c;h*=1099511628211ULL;}h^=s.size();return h*1099511628211ULL;}std::uint64_t hash_pair(std::uint64_t a,std::uint64_t b){std::uint64_t x=a^(b+0x9e3779b97f4a7c15ULL+(a<<6)+(a>>2));x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;return x^(x>>31);}static std::size_t power(std::size_t n){std::size_t p=1;while(p<n){if(p>static_cast<std::size_t>(-1)/2)throw std::overflow_error("tree");p*=2;}return p;}static std::uint64_t node(const std::vector<std::string>& l,std::size_t lo,std::size_t hi){if(hi-lo==1)return hash_leaf(l[std::min(lo,l.size()-1)]);auto m=lo+(hi-lo)/2;return hash_pair(node(l,lo,m),node(l,m,hi));}std::uint64_t root(const std::vector<std::string>& l){if(l.empty())throw std::invalid_argument("leaves");return node(l,0,power(l.size()));}static void emit(const std::vector<std::string>& l,const std::vector<std::size_t>& s,std::size_t lo,std::size_t hi,Proof& p){bool wanted=std::any_of(s.begin(),s.end(),[&](auto i){return i>=lo&&i<hi;});p.flags.push_back(wanted);if(!wanted){p.hashes.push_back(node(l,lo,hi));return;}if(hi-lo==1)return;auto m=lo+(hi-lo)/2;emit(l,s,lo,m,p);emit(l,s,m,hi,p);}Proof build(const std::vector<std::string>& l,const std::vector<std::size_t>& s){if(l.empty())throw std::invalid_argument("leaves");if(!std::is_sorted(s.begin(),s.end())||std::adjacent_find(s.begin(),s.end())!=s.end()||(!s.empty()&&s.back()>=l.size()))throw std::invalid_argument("selection");Proof p;emit(l,s,0,power(l.size()),p);return p;}static std::uint64_t read(std::size_t n,const std::vector<std::pair<std::size_t,std::string>>& m,const Proof& p,std::size_t lo,std::size_t hi,std::size_t& fi,std::size_t& hi_at,std::size_t& mi,bool& ok){if(fi>=p.flags.size()){ok=false;return 0;}bool descend=p.flags[fi++];if(!descend){if(hi_at>=p.hashes.size()){ok=false;return 0;}return p.hashes[hi_at++];}if(hi-lo==1){if(lo>=n||mi>=m.size()||m[mi].first!=lo){ok=false;return 0;}return hash_leaf(m[mi++].second);}auto mid=lo+(hi-lo)/2;auto a=read(n,m,p,lo,mid,fi,hi_at,mi,ok);auto b=read(n,m,p,mid,hi,fi,hi_at,mi,ok);return hash_pair(a,b);}bool verify(std::size_t n,const std::vector<std::pair<std::size_t,std::string>>& m,const Proof& p,std::uint64_t expected){if(!n||!std::is_sorted(m.begin(),m.end(),[](auto a,auto b){return a.first<b.first;})||std::adjacent_find(m.begin(),m.end(),[](auto a,auto b){return a.first==b.first;})!=m.end()||(!m.empty()&&m.back().first>=n))return false;std::size_t fi=0,hi=0,mi=0;bool ok=true;auto got=read(n,m,p,0,power(n),fi,hi,mi,ok);return ok&&got==expected;}}
